-- ============================================================================

values ('wellcorrelation', 'advanced', '{"modules":[{"key":"m01-predicting-a-missing-pick","title":"Predicting a Missing Pick","lesson_keys":["l01-the-problem","l02-what-you-are-allowed-to-assume","l03-the-three-wells-that-carry-it","l04-the-prediction-panel-map"]},{"key":"m02-the-layer-cake-estimate","title":"The Layer-Cake Estimate","lesson_keys":["l01-the-layer-cake-assumption","l02-the-mean-a-to-b-interval","l03-projecting-from-top-a","l04-where-layer-cake-fails"]},{"key":"m03-projecting-from-a-nearer-marker","title":"Projecting from a Nearer Marker","lesson_keys":["l01-why-the-starting-marker-matters","l02-the-mean-sand-to-b-interval","l03-projecting-from-top-sand","l04-shorter-projections-carry-less-error"]},{"key":"m04-the-spread","title":"The Spread","lesson_keys":["l01-two-methods-one-well","l02-the-eleven-metre-disagreement","l03-the-spread-is-the-uncertainty","l04-why-averaging-them-is-wrong","l05-which-estimate-to-prefer"]},{"key":"m05-relief-against-uncertainty","title":"Relief against Uncertainty","lesson_keys":["l01-what-structural-relief-is","l02-relief-is-not-the-error-bar","l03-reporting-a-predicted-pick","l04-what-would-settle-it"]},{"key":"m06-the-prediction-workflow","title":"The Prediction Workflow","lesson_keys":["l01-the-workflow-end-to-end","l02-quality-control","l03-the-capstone-walkthrough","l04-the-top-of-the-ladder"]}]}'::jsonb, 1)
