insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('wellcorrelation', 'advanced', 'module', 'm01-predicting-a-missing-pick', 1, 'Ekene-4 carries no TOP_B. What is the reason, and what does it imply about the well?', '["The surface was faulted out of the section at that location, which is why the interpreter left the slot blank rather than picking anything.","The pick was lost when the tops table was loaded and has to be recovered from the original interpretation.","The well reached total depth above TOP_B, so the surface was never drilled in that hole.","The log quality over that interval was too poor to support a confident pick."]'::jsonb, 2, 'Ekene-4''s deepest logged pick is BASE_SAND at 1615 m and the hole ended above TOP_B, so the rock was never drilled. The classic error is treating the blank as a data-quality defect to be repaired, which sends an interpreter back to logs that cannot contain the answer.'),
  ('wellcorrelation', 'advanced', 'module', 'm01-predicting-a-missing-pick', 2, 'Which set of picks does Ekene-4 actually carry?', '["TOP_A 1530 m, TOP_SAND 1590 m, BASE_SAND 1615 m","TOP_A at 1530 m, TOP_SAND at 1590 m, BASE_SAND at 1615 m and a predicted TOP_B","TOP_A at 1530 m, TOP_SAND at 1590 m and TOP_B at 1615 m","TOP_A 1512 m, TOP_SAND 1565 m and BASE_SAND 1601 m"]'::jsonb, 0, 'Ekene-4 has three measured picks and fifteen of the section''s sixteen slots are filled. The longest option embodies the classic error of listing a predicted depth alongside logged picks, which is how an estimate becomes a pick within a week.'),
  ('wellcorrelation', 'advanced', 'module', 'm01-predicting-a-missing-pick', 3, 'How should the blank in Ekene-4''s TOP_B slot be described?', '["A data-quality defect that should be closed by re-examining the logs and picking the surface the first interpreter missed.","A correct record that nobody observed the surface in that well.","A zero depth, which every statistic on TOP_B will handle correctly once the table is loaded.","A temporary gap that this tier''s prediction will fill in the tops table."]'::jsonb, 1, 'A missing top records an absence of observation and makes no claim about where the surface sits. Treating it as a zero is the classic error, because a zero is a depth and it corrupts every relief and mean computed on TOP_B.'),
  ('wellcorrelation', 'advanced', 'module', 'm01-predicting-a-missing-pick', 4, 'Which statement correctly describes what the missing pick costs downstream?', '["A map is unaffected, because contouring packages interpolate missing wells correctly.","A volume is unaffected, since gross rock volume needs one bounding surface.","A well plan is unaffected, because a prognosis can quote the nearest well''s depth.","Contouring TOP_B has three control points across the area the four wells cover, so the ground around Ekene-4 is drawn by an extrapolation nobody wrote down and nobody can inspect."]'::jsonb, 3, 'The map, the volume and the well plan all stall on the one empty cell. The three wrong options each assume the gap is absorbed silently somewhere downstream, which is exactly how an unwritten assumption enters a resource number.'),
  ('wellcorrelation', 'advanced', 'module', 'm01-predicting-a-missing-pick', 5, 'A drilling engineer asks for a TOP_B prognosis for a deepening of Ekene-4. What must your answer carry?', '["A predicted depth, a range around it, and the basis of both, meaning the marker it was projected from and the wells it was derived from.","A single depth, because a range would leave the casing design without a target.","The deepest logged TOP_B on the section, which is the safest number to plan against.","A depth quoted to the nearest metre, with the method left out of the memo."]'::jsonb, 0, 'A depth with no range invites a plan that treats it as certain, and a range with no basis cannot be revised when new data arrives. Quoting a bare single depth is the classic error, because the reader cannot tell it from a measurement.'),
  ('wellcorrelation', 'advanced', 'module', 'm01-predicting-a-missing-pick', 6, 'Which assumption are you permitted to make when predicting into Ekene-4?', '["That any interval measured in three wells is constant everywhere on the section, since those wells are the only evidence available.","That the deepest well on the section carries the deepest value of every surface.","That a missing surface can be picked from a neighbouring well''s log.","That the section behaves between wells roughly as it behaves at wells."]'::jsonb, 3, 'Borrowing a relationship observed at several places and applying it nearby is the foundation under every correlation line ever drawn. The longest option embodies the forbidden move, promoting a three-well observation into a property of the whole section.'),
  ('wellcorrelation', 'advanced', 'module', 'm01-predicting-a-missing-pick', 7, 'Why is a claim that the TOP_A to TOP_B interval is constant not an innocent assumption on this section?', '["Because TOP_B is not a correlatable surface when only three wells carry it.","Because the one interval all four wells can supply, TOP_A to TOP_SAND, has already been measured varying by 14 m.","Because Ekene-4''s TOP_A at 1530 m is the deepest on the section and therefore suspect.","Because the wells are too far apart to correlate at all."]'::jsonb, 1, 'The data has already contradicted constancy for the one interval every well can supply, with values of 48, 53, 46 and 60 m. The assumption can still be made openly as an approximation, and it cannot be made quietly.'),
  ('wellcorrelation', 'advanced', 'module', 'm01-predicting-a-missing-pick', 8, 'A prediction at this tier is built from two parts. Which pair?', '["An interpretation of the seismic character between the wells, and a depth conversion that carries it into the well that stopped short.","A best estimate and the interpreter''s stated confidence in it.","A stated assumption that could be false, and arithmetic any reader can reproduce.","A mean interval and a tolerance."]'::jsonb, 2, 'Keeping the assumption and the arithmetic apart means a disagreement lands on the assumption, where it belongs. Confidence in place of a stated assumption is the classic error, since confidence cannot be argued with or revised.'),
  ('wellcorrelation', 'advanced', 'module', 'm01-predicting-a-missing-pick', 9, 'Ekene-4 has the deepest TOP_A on the section at 1530 m. What does that fact establish about its TOP_B?', '["Nothing about interval thickness, because structural position and thickness are separate quantities.","That Ekene-4 must also carry the deepest TOP_B on the section, so the prediction can be checked against that requirement.","That Ekene-4 carries the thinnest section of the four wells.","That the layer-cake assumption is exact for this well."]'::jsonb, 0, 'A section that grows is one where structural position and interval thickness can move against each other. Treating the deepest TOP_A as proof of the deepest everything is the classic error, and it converts an expectation into evidence.'),
  ('wellcorrelation', 'advanced', 'module', 'm01-predicting-a-missing-pick', 10, 'What is Ekene-2''s TOP_A to TOP_B interval?', '["97 m, which is the distance from TOP_SAND down to TOP_B in that well.","133 m, which is the interval measured in Ekene-3.","150 m, since 1662 minus 1512 is 150.","140 m."]'::jsonb, 2, 'Both depths come from the same hole, which is what makes the result a measurement rather than a comparison between wells. The longest option is the classic error of subtracting from the wrong marker.'),
  ('wellcorrelation', 'advanced', 'module', 'm01-predicting-a-missing-pick', 11, 'What is Ekene-3''s TOP_SAND to TOP_B interval?', '["92 m, which is the mean of the three carrying wells for this interval.","87 m.","133 m, which is the TOP_A to TOP_B interval in the same well.","1628 m."]'::jsonb, 1, '1628 minus 1541 is 87 m. Quoting the mean of 92 m in place of the well''s own value is the classic error, because it substitutes a summary of three wells for a measurement made in one.'),
  ('wellcorrelation', 'advanced', 'module', 'm01-predicting-a-missing-pick', 12, 'The TOP_A to TOP_B intervals of the three carrying wells are 140, 150 and 133 m. What is their spread, and what is its status?', '["17 m, from 133 m to 150 m, and it is a floor, because a fourth carrier could only widen it.","17 m, from 133 m to 150 m, and it is the section''s full variability, because three wells bracket the range.","10 m, from 87 m to 97 m.","14 m, the growth range."]'::jsonb, 0, 'A range can only widen as wells are added, since a new value either falls inside the existing ends or extends one. Treating the observed spread as the section''s full variability is the classic error, and it makes the estimate look firmer than the sample supports.'),
  ('wellcorrelation', 'advanced', 'module', 'm01-predicting-a-missing-pick', 13, 'With only three carrying wells, which of these is not honestly available to you?', '["Computing a mean interval at all, because a mean of three observations has no defensible central value.","Measuring an interval inside a single wellbore.","Quoting a range for the estimate.","Validating the method by holding a well back."]'::jsonb, 3, 'Three carriers support a mean and a range, and they cannot support a demonstrated track record for the method. Refusing to compute the mean at all is the opposite error, and it discards a usable summary because the sample is small.'),
  ('wellcorrelation', 'advanced', 'module', 'm01-predicting-a-missing-pick', 14, 'You are drawing a section figure that shows where TOP_B might sit under Ekene-4. What stays as it was?', '["The correlation line is extended to Ekene-4 once the estimate is defensible.","The correlation line still stops after the third well, with any estimate drawn in a separate style under a legend entry naming it as estimated.","The estimate replaces the blank so that the figure looks finished.","The figure is left out of the report."]'::jsonb, 1, 'The correlation line is the observation and the dashed thing is the inference, and a reader can only choose between them if they are drawn differently. Extending the line is the classic error, since it makes an inference look like a pick at a glance.'),
  ('wellcorrelation', 'advanced', 'module', 'm01-predicting-a-missing-pick', 15, 'The TOP_B structural relief across the three wells that carry it is 34 m. What is that number?', '["The uncertainty on the predicted TOP_B in Ekene-4, since it is the spread of that surface on the section.","The mean TOP_A to TOP_B interval, rounded to the nearest metre.","How much TOP_B itself moves structurally, from 1628 m in Ekene-3 to 1662 m in Ekene-2.","The depth error in Ekene-4''s TOP_A pick."]'::jsonb, 2, 'Relief is a statement about the surface across the wells that have it, and it is a three-well number. Quoting relief as the error bar on a prediction is the classic error at this tier, because both quantities are differences in metres and both come off the same panel.'),
  ('wellcorrelation', 'advanced', 'module', 'm02-the-layer-cake-estimate', 1, 'Which is the layer-cake assumption, stated in the form this module uses it?', '["The layers are horizontal, so no well can be structurally deeper than another.","The vertical distance between two named surfaces is the same in every well, so a distance measured in one well transfers unchanged to another.","Each layer carries the same lithology in every well on the section.","The section can be flattened without changing any interval."]'::jsonb, 1, 'The assumption is about thickness rather than about attitude or lithology. The option about flattening is a true statement of a different idea, and mistaking it for layer-cake is the classic error, since flattening leaves intervals untouched whether or not they are constant.'),
  ('wellcorrelation', 'advanced', 'module', 'm02-the-layer-cake-estimate', 2, 'If this section really were a layer cake, what would be true of a projection from TOP_A and a projection from TOP_SAND?', '["They would land in the same place, because every interval would be constant, including the one between the two starting markers.","They would differ by the growth range of 14 m.","They would differ, because the two markers sit at different depths.","Only the deeper marker would give a usable answer."]'::jsonb, 0, 'Under a true layer cake there is no method dependence at all, which is why a disagreement between two constructions is informative. Expecting a difference because the markers are at different depths is the classic error, since the starting depth is subtracted out by the arithmetic.'),
  ('wellcorrelation', 'advanced', 'module', 'm02-the-layer-cake-estimate', 3, 'Which of these is friendly to the layer-cake assumption rather than hostile to it?', '["Growth faulting, since a fault active during deposition keeps the units parallel across it.","A channel system whose thickness changes over a few hundred metres.","An unconformity that cuts down further in one place than in another.","Post-depositional tilting, which moves surfaces without altering thickness."]'::jsonb, 3, 'Tilting and gentle folding move surfaces without changing the distance between them, which is why a section with strong structural relief can still be an excellent layer cake. The longest option inverts the growth-fault case, which is the standard way the assumption fails.'),
  ('wellcorrelation', 'advanced', 'module', 'm02-the-layer-cake-estimate', 4, 'How does growth faulting break the layer-cake assumption?', '["It removes section at the fault plane and leaves the interval unchanged everywhere else.","It tilts the whole stack, so every interval increases by the same amount.","It creates more accommodation on the downthrown side, so units thicken toward the fault and thin away from it.","It makes the tops harder to pick and leaves the thicknesses alone."]'::jsonb, 2, 'A fault active while sediment accumulated makes the interval a function of position, so the bounding surfaces stop being parallel. The option about tilting is the classic error, because it confuses a change of attitude with a change of thickness.'),
  ('wellcorrelation', 'advanced', 'module', 'm02-the-layer-cake-estimate', 5, 'Which measured fact shows the Ekene section is not a layer cake?', '["The TOP_B structural relief of 34 m across the three wells that carry the surface.","The four wells report different TOP_A depths.","One well is missing a top.","The growth range of 14 m."]'::jsonb, 3, 'Only a varying interval shows that two surfaces are not parallel, and TOP_A to TOP_SAND is the one interval all four wells can supply. Citing relief instead is the classic error, since relief is unaffected by whether the section grows.'),
  ('wellcorrelation', 'advanced', 'module', 'm02-the-layer-cake-estimate', 6, 'How is each of the three TOP_A to TOP_B intervals obtained?', '["By comparing TOP_B in one well against TOP_A in the next, which is what makes the values comparable across the section.","As one subtraction inside one wellbore, so Ekene-1 gives 1640 minus 1500, which is 140 m.","By averaging the four wells'' TOP_A depths and subtracting each TOP_B from the result.","By reading them off the flattened display."]'::jsonb, 1, 'Both depths in each subtraction come from the same hole, which is what makes each result a measurement. Crossing wells inside the subtraction is the classic error, and it produces a comparison rather than an interval.'),
  ('wellcorrelation', 'advanced', 'module', 'm02-the-layer-cake-estimate', 7, 'What is the mean TOP_A to TOP_B interval of the three carrying wells?', '["The mean cannot be computed until Ekene-4''s own interval has been included.","141.5 m, from 283 divided by 2.","141 m, from 423 divided by 3.","140 m, Ekene-1''s value."]'::jsonb, 2, '140 plus 150 plus 133 is 423, and 423 divided by 3 is exactly 141 m. The longest option is the classic error of trying to average in the well that lacks the target top, which is the well the mean exists to serve.'),
  ('wellcorrelation', 'advanced', 'module', 'm02-the-layer-cake-estimate', 8, 'Why is the mean preferred to the median on this sample of three intervals?', '["The median is undefined for three observations, so no central value could be quoted without a fourth well.","The median would return 140 m and discard two wells.","The median would return 150 m and overstate the interval.","The median is harder to compute by hand."]'::jsonb, 1, 'On a sample of three, taking the median is close to picking one well and calling it representative. Claiming the median is undefined is the classic error, since three ordered values have a perfectly well defined middle one.'),
  ('wellcorrelation', 'advanced', 'module', 'm02-the-layer-cake-estimate', 9, 'What has to be quoted beside the mean of 141 m for the number to be usable?', '["The 17 m spread of its three inputs, from 133 m to 150 m.","The 14 m growth range of the TOP_A to TOP_SAND interval, which is the spread of these same inputs.","The grading tolerance, which states the uncertainty on the estimate.","Nothing, because a mean is a single value."]'::jsonb, 0, 'The mean is what you compute with and the spread is what tells a reader how much the mean deserves to be trusted. Treating the grading tolerance as the uncertainty is the classic error, since a tolerance is a marking allowance rather than a statement about the section.'),
  ('wellcorrelation', 'advanced', 'module', 'm02-the-layer-cake-estimate', 10, 'Recompute the mean TOP_A to TOP_B interval with Ekene-2 excluded. What do you get, and how does it compare?', '["141 m, because removing one input does not move a mean.","150 m, the value that the dropped well carried.","273 m.","136.5 m, 4.5 m below the three-well mean."]'::jsonb, 3, 'The remaining intervals are 140 m and 133 m, their sum is 273, and the mean is 136.5 m. Believing a mean is stable against dropping an input is the classic error, and here one well of three carries about a third of the weight.'),
  ('wellcorrelation', 'advanced', 'module', 'm02-the-layer-cake-estimate', 11, 'Which statement gives the layer-cake estimate for Ekene-4''s TOP_B correctly?', '["1671 m, predicted, from 1530 plus 141.","From 1590 plus 141, anchoring on TOP_SAND with the TOP_A to TOP_B interval.","1671 m, which can now be entered as Ekene-4''s TOP_B pick.","1641.5 m, predicted, from 1500 plus 141.5."]'::jsonb, 0, 'The estimate is Ekene-4''s own TOP_A plus the mean interval measured in the three other wells. Pairing an interval with a marker it was not measured from is the classic error, and it silently changes the assumption being made.'),
  ('wellcorrelation', 'advanced', 'module', 'm02-the-layer-cake-estimate', 12, 'In the sum 1530 plus 141, where does the uncertainty in the result live?', '["In both terms about equally, since Ekene-4''s TOP_A pick is as uncertain as the borrowed interval and the two errors partly cancel.","In the 1530 m, which is the only number local to the well.","Entirely in the 141 m, which was measured in three other wells and transfers one metre of error for each metre it is wrong.","In the addition, which rounds."]'::jsonb, 2, 'One term is a local measurement and the other is a borrowed average, so all of the transfer risk sits in the second. Expecting the errors to damp each other is the classic error, since nothing in a single addition averages anything.'),
  ('wellcorrelation', 'advanced', 'module', 'm02-the-layer-cake-estimate', 13, 'Where should the value of 1671 m be recorded?', '["In the tops table, since a defensible estimate with a stated method serves downstream mapping and volume work as well as a pick does.","As a predicted depth, in the report or in a clearly named estimate column, with Ekene-4''s TOP_B slot left blank.","As a pick, with a note in the comments field.","Nowhere, since it was never logged."]'::jsonb, 1, 'A tops table has no column for how a depth came to be there, so an estimate entered in it becomes a pick. Entering the value because it is defensible is the classic error, and it discards the range, which was the most valuable part of the work.'),
  ('wellcorrelation', 'advanced', 'module', 'm02-the-layer-cake-estimate', 14, 'Which sanity check does the estimate of 1671 m pass?', '["It sits below BASE_SAND at 1615 m.","It is shallower than every logged TOP_B on the section, which is what the deepest TOP_A requires.","It matches Ekene-2''s TOP_B of 1662 m.","It lies inside the drilled interval."]'::jsonb, 0, 'A predicted TOP_B must lie below the well''s deepest logged surface and below total depth, and 1671 m sits 56 m below BASE_SAND. The option about lying inside the drilled interval is the classic error, since it contradicts the reason the pick is missing.'),
  ('wellcorrelation', 'advanced', 'module', 'm02-the-layer-cake-estimate', 15, 'Why is the layer-cake estimate specifically weak at Ekene-4 rather than weak in general?', '["Ekene-4''s TOP_A pick is less reliable than the other three.","The three carrying wells are too far away for the section to correlate.","Ekene-4 carries the thickest TOP_A to TOP_SAND interval on the section at 60 m against a 46 to 60 m range, and all three contributing wells are thinner there.","The mean of 141 m was computed from four wells rather than three."]'::jsonb, 2, 'The mean was built from wells other than the one being predicted into, so it is blind to the one piece of local evidence available about Ekene-4''s section. Blaming the TOP_A pick is the classic error, since that depth is a measurement and carries no transfer risk.'),
  ('wellcorrelation', 'advanced', 'module', 'm03-projecting-from-a-nearer-marker', 1, 'A prediction of a missing pick, as this module frames it, is built from two parts. What are they?', '["An average of the target surface depths in the wells that carry it, corrected for how deep the predicted well sits relative to those wells, then rounded to the metre.","A displayed depth taken from the flattened panel plus that well''s flattening shift.","A measured pick in the well being predicted, used as an anchor, plus an interval borrowed from the wells that carry the target surface.","Two measured picks in the predicted well, subtracted."]'::jsonb, 2, 'The anchor is measured in the well being predicted and the borrowed interval is the assumption, which is why the two are reported separately. Averaging the target depths and correcting for structure is a different construction that this module does not use.'),
  ('wellcorrelation', 'advanced', 'module', 'm03-projecting-from-a-nearer-marker', 2, 'Which of these can NOT serve as the anchor for a prediction of TOP_B in Ekene-4?', '["Ekene-2''s TOP_B at 1662 m, since that depth belongs to another wellbore.","Ekene-4''s TOP_A at 1530 m.","Ekene-4''s TOP_SAND at 1590 m.","Ekene-4''s BASE_SAND at 1615 m."]'::jsonb, 0, 'An anchor has to be a depth the well being predicted actually has, so it comes from Ekene-4''s own three measured picks. Reaching for a pick in a carrier well confuses the anchor with the borrowed interval.'),
  ('wellcorrelation', 'advanced', 'module', 'm03-projecting-from-a-nearer-marker', 3, 'The TOP_SAND to TOP_B intervals in the three wells that carry both surfaces are 92, 97 and 87 m. What is the mean interval the prediction borrows?', '["276 m, the sum of the three intervals before dividing by the number of wells.","141 m, which is the mean measured from TOP_A rather than from TOP_SAND.","97 m, the largest of the three intervals.","92 m."]'::jsonb, 3, 'The three intervals sum to 276 and divide exactly by 3 to give 92 m. Quoting 276 m is the classic error of stopping at the sum, and 141 m is the mean belonging to the other anchor.'),
  ('wellcorrelation', 'advanced', 'module', 'm03-projecting-from-a-nearer-marker', 4, 'Which wells contribute measurements to the mean TOP_SAND to TOP_B interval used to predict Ekene-4''s TOP_B?', '["All four wells, using Ekene-4''s predicted TOP_B once a first estimate of it exists, so that the mean reflects the whole section.","Ekene-1, Ekene-2 and Ekene-3, the three wells that carry both surfaces.","Ekene-1 and Ekene-3 only, since Ekene-2 sits at the thick end of the range.","Ekene-4 alone, because the prediction is about that well."]'::jsonb, 1, 'Only wells carrying both ends of the interval can measure it, which is the three carriers. Feeding a first estimate back into the mean is circular, since the prediction would then be built partly from itself.'),
  ('wellcorrelation', 'advanced', 'module', 'm03-projecting-from-a-nearer-marker', 5, 'The three TOP_SAND to TOP_B intervals spread 10 m and the three TOP_A to TOP_B intervals spread 17 m. What does the tighter spread support?', '["The predicted TOP_B can be quoted as 1682 m plus or minus 10 m, since the input spread is the error bar on the prediction.","The section between TOP_SAND and TOP_B does not grow at all.","The from TOP_SAND estimate has been shown to be correct.","Borrowing the shorter interval is a smaller claim, because the carriers agree more closely about it."]'::jsonb, 3, 'Closer agreement among the carriers is the only direct evidence that an interval is stable enough to borrow. Treating the input spread as an error bar on the predicted depth is a misreading, since it describes the three measurements rather than the prediction.'),
  ('wellcorrelation', 'advanced', 'module', 'm03-projecting-from-a-nearer-marker', 6, 'Ekene-4''s measured TOP_SAND is 1590 m and the mean TOP_SAND to TOP_B interval borrowed from the three carriers is 92 m. What is the predicted TOP_B?', '["1676.5 m, the midpoint of the two estimates, which the module refuses.","1602 m, built from the displayed depth on the 1450 m datum.","1682 m.","1671 m, the layer-cake estimate."]'::jsonb, 2, 'The prediction is the measured anchor plus the borrowed interval, so 1590 plus 92 gives 1682 m. The 1602 m option is the frame error of projecting from a displayed depth rather than a measured one.'),
  ('wellcorrelation', 'advanced', 'module', 'm03-projecting-from-a-nearer-marker', 7, 'A colleague reports a predicted TOP_B of 1602 m for Ekene-4, obtained by adding 92 m to a TOP_SAND depth of 1510 m. What went wrong?', '["The 1510 m is a displayed depth, and predictions are built in measured depth.","Nothing went wrong with the arithmetic, so 1602 m is a third valid estimate and the spread across the estimates should now be widened to match.","The borrowed interval should have been the 141 m mean measured from TOP_A rather than the 92 m mean.","Ekene-4''s TOP_SAND was mispicked."]'::jsonb, 0, 'The 1510 m is Ekene-4''s TOP_SAND as displayed on the 1450 m datum, and a displayed depth belongs to a chosen datum rather than to the earth. Accepting the result as a further estimate compounds the frame error instead of catching it.'),
  ('wellcorrelation', 'advanced', 'module', 'm03-projecting-from-a-nearer-marker', 8, 'The predicted TOP_B of 1682 m in Ekene-4 is deeper than all three measured TOP_B picks of 1640, 1662 and 1628 m. What should you make of that?', '["It shows the prediction is wrong, since a prediction must fall inside the range of its inputs.","It is expected rather than alarming, because Ekene-4 sits deeper than the other three wells on every marker it does carry, so it should sit deeper on the next surface down.","It means the borrowed interval was applied in the wrong direction.","It confirms the prediction is correct."]'::jsonb, 1, 'Ekene-4 is the deepest well in the section on TOP_A and on TOP_SAND, so a deeper predicted TOP_B is consistent with the structure. Requiring a prediction to land inside the range of the measured picks confuses an interval projection with an interpolation.'),
  ('wellcorrelation', 'advanced', 'module', 'm03-projecting-from-a-nearer-marker', 9, 'Which of these reports the from TOP_SAND result in the form the module asks for?', '["Predicted TOP_B in Ekene-4, 1682 m, estimated by projecting the three well mean TOP_SAND to TOP_B interval of 92 m from the measured TOP_SAND at 1590 m.","Ekene-4 TOP_B, 1682 m, high confidence.","Ekene-4 TOP_B is about 1680 m.","Ekene-4 TOP_B, 1682 m."]'::jsonb, 0, 'A usable report carries the value, the method, the wells behind it and the status of the result. A bare depth in a tops line is read as a pick, which is the error the labelling discipline exists to prevent.'),
  ('wellcorrelation', 'advanced', 'module', 'm03-projecting-from-a-nearer-marker', 10, 'You have produced a defensible predicted TOP_B for Ekene-4. What happens to the tops table and to the count of wells carrying all four tops?', '["The slot is filled with 1682 m and the count rises to 4, since the value now has a stated method behind it.","The slot is filled with 1682 m while the count stays at 3.","The slot stays blank while the count rises to 4.","The slot stays blank and the count stays at 3."]'::jsonb, 3, 'A prediction is an estimate and never becomes a pick, however well it was made, so the tops table entry and the well count are both untouched. Filling the slot because the method was rigorous is the error that silently corrupts every statistic built on TOP_B.'),
  ('wellcorrelation', 'advanced', 'module', 'm03-projecting-from-a-nearer-marker', 11, 'Which of these is NOT one of the grounds the module offers for preferring the from TOP_SAND estimate?', '["The three carriers agree more closely about the borrowed interval, spreading 10 m against 17 m.","It was checked against the TOP_B depth logged in Ekene-4.","The anchor sits below the stretch where Ekene-4 runs thick.","The projection is shorter, at 92 m against 141 m."]'::jsonb, 1, 'Ekene-4 stopped above TOP_B, so no logged depth exists there to check anything against. Believing a check was available is the error that turns a preference into a claim of proof.'),
  ('wellcorrelation', 'advanced', 'module', 'm03-projecting-from-a-nearer-marker', 12, 'Ekene-4 carries 60 m between TOP_A and TOP_SAND while the three carriers average 49 m over the same stretch. Why does that favour the from TOP_SAND route?', '["It does not favour either route, since a difference in one interval cannot affect a prediction of a surface lying below both of the markers involved.","It does not favour either route, since both use the same three carrier wells and the same target surface.","That route starts below the thickened stretch, so the extra thickness is already in the anchor.","It favours it because thick sections are picked more reliably."]'::jsonb, 2, 'Ekene-4''s extra thickness above TOP_SAND is recorded in the 1590 m anchor rather than assumed away, while the layer-cake route borrows an average that treats the well as typical over that stretch. Arguing that an interval above both markers cannot matter misses that the layer-cake route projects straight through it.'),
  ('wellcorrelation', 'advanced', 'module', 'm03-projecting-from-a-nearer-marker', 13, 'Which claim does the module explicitly refuse to make?', '["That the layer-cake estimate was built correctly from the available data and stays defensible even though it is not the preferred one.","That a shorter projection is always the better one, whatever the data show.","That the from TOP_SAND estimate rests on a smaller assumption.","That the anchor depth itself is measured."]'::jsonb, 1, 'The argument rests on spreads and on an anomaly measured in this section, so it does not generalise into a rule that nearer anchors always win. A nearer marker that was poorly picked could support a worse prediction than a distant one with clean control.'),
  ('wellcorrelation', 'advanced', 'module', 'm03-projecting-from-a-nearer-marker', 14, 'A colleague proposes dropping Ekene-2 from the mean because its 97 m interval sits at the thick end of the three. When is dropping a well from an average like this defensible?', '["Only when there is an independent reason to doubt its picks, such as a mispick, a depth reference error or a fault cutting out section.","When it tightens the spread of the remaining inputs and brings the two predictions closer together.","Whenever a well sits at either end of the range.","When it moves the prediction nearer the other method."]'::jsonb, 0, 'A well is removed for a reason found in the data, never for sitting at the edge of a range. Dropping the extreme value narrows the apparent spread because a measurement was deleted, which manufactures confidence rather than earning it.'),
  ('wellcorrelation', 'advanced', 'module', 'm03-projecting-from-a-nearer-marker', 15, 'The mean TOP_SAND to TOP_B interval of 92 m happens to equal Ekene-1''s own interval of 92 m exactly. What should you conclude from that?', '["That Ekene-1 is the best analogue for Ekene-4, so its interval should be used on its own rather than the mean of the three.","That the three intervals must be equal.","That the mean was computed wrongly.","Nothing, since it is a coincidence of these three wells."]'::jsonb, 3, 'A mean is not obliged to land on one of its inputs and here it does so by chance, since 92, 97 and 87 average to 92. Promoting the matching well to best analogue reads a coincidence as evidence.'),
  ('wellcorrelation', 'advanced', 'module', 'm04-the-spread', 1, 'The layer-cake estimate is 1671 m and the from TOP_SAND estimate is 1682 m. What is the spread between them?', '["14 m, the growth range of the A-to-SAND interval measured in the tier below.","11 m.","17 m, the spread of the three TOP_A to TOP_B intervals.","1676.5 m, the midpoint of the two estimates."]'::jsonb, 1, 'The spread is one subtraction, 1682 minus 1671. Quoting the 14 m growth range or the 17 m input spread substitutes a different measured quantity for the disagreement between the two predictions.'),
  ('wellcorrelation', 'advanced', 'module', 'm04-the-spread', 2, 'Could the 11 m gap be an accumulation of rounding in the two calculations?', '["Yes, because dividing 423 by 3 and 276 by 3 each leaves a small remainder that carries through into the predicted depths.","Yes, because the borrowed intervals were rounded to the metre.","No, because rounding always cancels on subtraction.","No, both means divide exactly and every depth involved is an integer."]'::jsonb, 3, 'The A-to-B intervals sum to 423 and the SAND-to-B intervals to 276, and both divide by 3 without remainder, so no rounding enters either chain. Treating the gap as arithmetic slop is the first wrong instinct the module names.'),
  ('wellcorrelation', 'advanced', 'module', 'm04-the-spread', 3, 'In the identity for the spread, the difference between the two mean intervals is 141 minus 92, which is 49 m. What quantity is that?', '["The mean TOP_A to TOP_SAND interval across the three carriers, whose values are 48, 53 and 46 m.","Ekene-4''s own TOP_A to TOP_SAND interval.","The growth range of the A-to-SAND interval.","Half the spread between the two estimates."]'::jsonb, 0, 'In every well the A-to-B interval is the A-to-SAND interval plus the SAND-to-B interval, so the difference of the two means is the carriers'' mean A-to-SAND interval. Ekene-4''s own value over that stretch is 60 m, which is the other term of the identity rather than this one.'),
  ('wellcorrelation', 'advanced', 'module', 'm04-the-spread', 4, 'The identity evaluates to 60 minus 49, which is 11. What does that arithmetic say the disagreement is?', '["How much structural movement there is on TOP_B across the wells that carry it, expressed in the units of the prediction.","How much the two borrowed intervals differ in length.","How far Ekene-4''s own upper interval departs from the carriers'' average upper interval.","How much rounding the two routes accumulated."]'::jsonb, 2, 'The identity contains exactly two terms, Ekene-4''s own A-to-SAND interval of 60 m and the carriers'' mean of 49 m, so the gap measures the target well''s departure from the wells it borrowed from. Reading it as movement of TOP_B itself is the error of quoting a structural quantity where a prediction uncertainty is wanted.'),
  ('wellcorrelation', 'advanced', 'module', 'm04-the-spread', 5, 'Suppose a fifth well in this section carried a TOP_A to TOP_SAND interval of exactly 49 m, the carriers'' mean, and was missing TOP_B in the same way. What spread would the two methods give for that well?', '["Exactly 0 m, since the identity subtracts the carriers'' mean upper interval from the target well''s own.","11 m, the same as Ekene-4, because the spread between these two methods is a fixed property of the pair of constructions rather than of the well they are applied to.","About 1 m, because some disagreement always remains.","14 m, the growth range."]'::jsonb, 0, 'The identity is the target well''s own upper interval minus the carriers'' mean, so a well sitting on that mean gives zero and the two methods agree to the metre. Carrying Ekene-4''s 11 m across to another well treats a measured property of one well as a fixed feature of the technique.'),
  ('wellcorrelation', 'advanced', 'module', 'm04-the-spread', 6, 'Is the identity that produces the 11 m an exact result or an approximation?', '["An approximation, good on this section because the wells are close together and the intervals are similar, and it would degrade on a more variable section.","Exact, since subtracting one construction from the other collects the mean terms algebraically and leaves no error term behind, whatever the section it is applied to happens to look like.","An approximation, since the target well was never drilled to TOP_B.","Exact only because the numbers here divide without remainder."]'::jsonb, 1, 'Subtracting one construction from the other collects the mean terms algebraically, so the result holds for any well and any pair of markers. That the depths here are integers is convenient and is not what makes the identity exact.'),
  ('wellcorrelation', 'advanced', 'module', 'm04-the-spread', 7, 'On a section where every interval is constant across the wells, what do the two prediction methods give?', '["Two depths that differ by an amount set by how deep the target well sits relative to the others.","Two depths that differ by less than a metre.","The same depth, but only after averaging.","The same depth exactly."]'::jsonb, 3, 'With no growth the target well''s upper interval equals the carriers'' mean, the identity returns zero and the predictions coincide. The methods separate only when the surfaces bounding the borrowed intervals are not parallel.'),
  ('wellcorrelation', 'advanced', 'module', 'm04-the-spread', 8, 'The spread measures exactly one thing. Which?', '["How much TOP_B moves structurally across the wells that carry it, which is why it belongs with the structural readings rather than with the prediction.","How reliable the TOP_B picks in the three carrier wells were judged to be by the interpreter.","How far Ekene-4 departs from the carriers over the stretch above TOP_SAND.","How long the two projections are."]'::jsonb, 2, 'The identity leaves only two terms standing, so nothing else enters: not the structural position of TOP_B, not pick quality, not the length of either projection. Filing the spread as a structural reading is the misclassification the tier warns about.'),
  ('wellcorrelation', 'advanced', 'module', 'm04-the-spread', 9, 'The from TOP_SAND estimate lands deeper than the layer-cake estimate here. Is that a property of the two methods?', '["Yes, projecting from a deeper anchor always produces a deeper prediction, whatever the target well''s thickness happens to be.","No, it follows from TOP_B being the deepest surface in the section.","Yes, because the borrowed interval is shorter.","No, it follows from Ekene-4 running thick."]'::jsonb, 3, 'The identity is signed, so a target well thicker than the carriers over the upper stretch pushes the from TOP_SAND result deeper and a thinner one would reverse the order. Memorising which method gives the deeper answer turns a property of this well into a false rule.'),
  ('wellcorrelation', 'advanced', 'module', 'm04-the-spread', 10, 'What makes the 11 m different from an error bar of plus or minus 10 m that an interpreter attaches from experience?', '["It was produced by the data, so it moves when the data move and would be zero on a section without growth.","It came from two methods rather than one, so it is twice as reliable as a single estimate would be.","It is quoted without a plus or minus sign.","It is larger, so it is more cautious."]'::jsonb, 0, 'A derived uncertainty responds to the section it was measured on, while an attached one describes the habits of the person quoting it. Counting methods rather than looking at where the number came from misses that distinction.'),
  ('wellcorrelation', 'advanced', 'module', 'm04-the-spread', 11, 'Why does the report say a predicted TOP_B of about 1671 to 1682 m rather than 1671 to 1682 m?', '["Because a range quoted without a qualifier would be read as a hard limit on where the surface can be, which is not what two estimates establish.","Because the two estimates were rounded to the nearest metre and the true value lies somewhere between them.","Pick error, the three well sample and unseen structure all sit outside the 11 m.","Because a range is always quoted loosely."]'::jsonb, 2, 'The 11 m measures sensitivity to the choice of projection marker and nothing else, so it is a floor rather than a full accounting of the uncertainty. Pick error, the small sample of three wells and the chance of unseen structure are the components the module names as sitting outside it.'),
  ('wellcorrelation', 'advanced', 'module', 'm04-the-spread', 12, 'Which statement reports the prediction as this module asks?', '["Predicted TOP_B in Ekene-4 of 1676.5 m, obtained by averaging a layer-cake estimate and a nearer-marker estimate that differ by 11 m, which removes the need to report a range.","Predicted TOP_B in Ekene-4 between about 1671 and 1682 m, from two projections off different markers, with the 11 m spread reflecting growth in the A-to-SAND interval.","Predicted TOP_B in Ekene-4, 1682 m.","TOP_B in Ekene-4 is at 1671 m."]'::jsonb, 1, 'The report carries the range, the method, the cause of the spread and the status of the result. Averaging into a midpoint deletes the range, which is the one quantity the exercise measured rather than assumed.'),
  ('wellcorrelation', 'advanced', 'module', 'm04-the-spread', 13, 'What does reporting 1676.5 m destroy?', '["Nothing, since the two estimates are still recorded in the working files and can be recovered later by anyone who thinks to ask about them.","The layer-cake estimate, which no longer appears anywhere in the reported result even though it was defensible.","The measured range, which was the only uncertainty the data produced.","The anchor depth."]'::jsonb, 2, 'A reader given a midpoint cannot recover the range, cannot tell that a methodological choice was made, and cannot see how far apart the two methods were. Relying on the working files to preserve it is the assumption that fails six months later when the number is read on its own.'),
  ('wellcorrelation', 'advanced', 'module', 'm04-the-spread', 14, 'Why is the midpoint not the best single estimate here?', '["Because the midpoint of two numbers is never one of them, so it cannot be defended by either of the methods that produced it.","Because the true depth is known to lie nearer to the deeper of the two estimates.","Because averaging is a valid operation only on three or more independent values.","They are not independent and the gap is systematic."]'::jsonb, 3, 'Both estimates come from the same three wells and the SAND-to-B interval sits inside the A-to-B interval in each, so their errors do not cancel the way independent measurements do, and the identity shows the gap has a direction rather than random scatter. Nothing in the section says the true depth is nearer either end.'),
  ('wellcorrelation', 'advanced', 'module', 'm04-the-spread', 15, 'If a single number is genuinely required, the module reports 1682 m. What is the status of that choice?', '["A judgement resting on stated grounds, with the range of about 1671 to 1682 m still travelling with it, since nobody drilled the surface.","A proof that 1682 m is the correct depth.","A result that removes the need to report the other estimate.","A convention that applies to any missing pick."]'::jsonb, 0, 'The grounds argue that one estimate rests on a smaller and better supported assumption, which is a statement about the reasoning rather than about where the surface lies. Reading a preference as a proof is the error the lesson refuses in the same breath as it makes the choice.'),
  ('wellcorrelation', 'advanced', 'module', 'm05-relief-against-uncertainty', 1, 'In this course, the structural relief of a named surface across a section is which quantity?', '["The maximum minus the minimum of the interval between that surface and the one above it, across the wells","The spread of the surface''s displayed depths after the section is flattened on a datum","The deepest measured pick of that surface minus its shallowest measured pick, taken over the wells that carry it","The difference between two predicted depths for the surface"]'::jsonb, 2, 'Relief uses one surface and one pick per well. The first distractor is the growth range, which uses two surfaces and two picks per well, and swapping relief for growth is the standard error.'),
  ('wellcorrelation', 'advanced', 'module', 'm05-relief-against-uncertainty', 2, 'What is the structural relief of TOP_B across the Ekene section, and over how many wells?', '["34 m over three wells","34 m over four wells, since there are four wells drawn on the section panel","49 m over four wells, which is the largest relief measured on this section","11 m over three wells, matching the spread between the two predictions"]'::jsonb, 0, 'TOP_B is picked at 1640, 1662 and 1628 m, so the relief is 1662 minus 1628, which is 34 m over three wells. Quoting four wells hides that Ekene-4 has no TOP_B, and the 11 m option is the classic swap of the prediction spread for a relief.'),
  ('wellcorrelation', 'advanced', 'module', 'm05-relief-against-uncertainty', 3, 'Which well supplies the deep end of the TOP_B relief, and why is it not Ekene-4?', '["Ekene-4 at 1615 m, because that well carries the deepest measured pick of every surface on the section","Ekene-3 at 1628 m, because Ekene-3 carries the shallowest TOP_A of the four wells","Ekene-1 at 1640 m, because Ekene-1 is the first well in the section","Ekene-2 at 1662 m, because Ekene-4 has no TOP_B pick"]'::jsonb, 3, 'Ekene-4 has the deepest TOP_A, TOP_SAND and BASE_SAND, which makes the first distractor tempting, but the well reached total depth above TOP_B so it cannot supply that surface''s deep end. The deepest measured TOP_B is Ekene-2 at 1662 m.'),
  ('wellcorrelation', 'advanced', 'module', 'm05-relief-against-uncertainty', 4, 'A prediction places Ekene-4''s TOP_B at 1682 m. What should happen to the reported TOP_B relief of 34 m?', '["It should be revised to 54 m, since 1682 minus 1628 is now the deepest minus the shallowest value available","Nothing, because relief is defined on drilled picks and a predicted depth is not a pick","It should be revised to 43 m, using the layer-cake estimate of 1671 m as the deep end instead","It should be revised to 11 m, because the prediction spread now bounds the surface"]'::jsonb, 1, 'Relief counts drilled surfaces only, so the reported 34 m over three wells stands. Feeding a predicted depth into a relief calculation is the error the first two distractors embody.'),
  ('wellcorrelation', 'advanced', 'module', 'm05-relief-against-uncertainty', 5, 'Someone asks how much the interval between TOP_A and TOP_SAND varies across the Ekene wells. What is the answer, and what habit tells you which quantity is wanted?', '["14 m, and the habit is to count the surfaces named in the question, since two surfaces means an interval and variation in it is growth","49 m, and the habit is to read the spread of the lower surface across the section, since TOP_SAND is the surface that visibly moves from well to well","35 m, because TOP_A is the anchor and its relief controls the interval below it","11 m, because that is the measured variation on this section"]'::jsonb, 0, 'Two named surfaces means an interval, so the answer is the growth range of 14 m from intervals of 48, 53, 46 and 60 m. Answering 49 m quotes the relief of TOP_SAND, which is roughly three times too large and attributes structure to thickness change.'),
  ('wellcorrelation', 'advanced', 'module', 'm05-relief-against-uncertainty', 6, 'What does the 11 m spread measure, and what does the 34 m relief measure?', '["The spread measures how much the TOP_B surface itself moves structurally across the three wells, and the relief measures how much the two prediction methods disagree about the Ekene-4 depth","Both measure the uncertainty on the Ekene-4 prediction, stated at two different confidence levels","The spread measures how much two methods disagree about one depth in Ekene-4, and the relief measures how much the TOP_B surface itself moves across three drilled wells","Both measure the same structural spread, read at two stages of the workflow"]'::jsonb, 2, 'One number counts methods on a single well and the other counts a surface across wells. Treating them as two readings of one quantity is the classic mistake at this tier.'),
  ('wellcorrelation', 'advanced', 'module', 'm05-relief-against-uncertainty', 7, 'Which observation shows most directly that the 34 m relief cannot be the error bar on the Ekene-4 prediction?', '["The relief was computed from the three wells that carry TOP_B, while the two predictions were computed from all four wells in the section including Ekene-4 itself","Both estimates, 1671 m and 1682 m, are deeper than the deepest measured TOP_B at 1662 m, so a band drawn from the relief would not contain either answer","34 m is larger than 11 m, and an error bar is always the smaller of the ranges available","Relief changes when the section is flattened, and a prediction does not"]'::jsonb, 1, 'The two quantities do not even describe overlapping intervals of depth, which is the fastest way to see the swap is wrong. Both predictions and the relief use the same three wells, and relief is defined on measured depths so flattening leaves it alone.'),
  ('wellcorrelation', 'advanced', 'module', 'm05-relief-against-uncertainty', 8, 'In a section where every interval were constant, what would happen to the spread and to the relief?', '["Both would fall to zero, since a constant-interval section has no variation of any kind left in it","Relief would fall to zero and the spread would stay at 11 m","Both would be unchanged, since neither depends on how the section thickens","The spread would fall to zero and the relief would be unchanged"]'::jsonb, 3, 'A layer cake can sit at any tilt, so its surfaces still have relief while both estimates land on the same depth. This is the cleanest test that the two ideas have separated, since it shows the relief is not a rival estimate of the spread.'),
  ('wellcorrelation', 'advanced', 'module', 'm05-relief-against-uncertainty', 9, 'The 11 m spread has an exact meaning of its own. Which statement gives it?', '["It is Ekene-4''s own A-to-SAND interval of 60 m minus the three carriers'' mean A-to-SAND of 49 m","It is the growth range of the A-to-SAND interval taken across all four wells of the section, which comes to 14 m","It is roughly a third of the 34 m structural relief of TOP_B, which is the reason the two numbers are so often confused","It is an approximate figure reflecting the general fact that the section grows"]'::jsonb, 0, 'The carriers'' intervals of 48, 53 and 46 m average to 49 m, which is also 141 minus 92, so 60 minus 49 gives the spread exactly. The spread is a derived quantity with a specific meaning rather than a rough consequence of growth.'),
  ('wellcorrelation', 'advanced', 'module', 'm05-relief-against-uncertainty', 10, 'A mapper contouring TOP_B and a drilling engineer planning to deepen Ekene-4 each ask you for a number. Which number does each one get?', '["Both get the 34 m relief over three wells, because it is the more conservative of the two figures and a larger range covers either reader safely","The mapper gets the 11 m spread and the engineer gets the 34 m relief","Both get 1676.5 m, which is the single best estimate available","The mapper gets the 34 m relief over three wells, and the engineer gets the predicted range of 1671 m to 1682 m with its 11 m spread"]'::jsonb, 3, 'Relief answers a structural question and the spread answers a confidence question, so each reader gets the one that matches. Handing 34 m to the engineer as the uncertainty is the classic error, and it is triple the measured disagreement.'),
  ('wellcorrelation', 'advanced', 'module', 'm05-relief-against-uncertainty', 11, 'Which set names the six elements a predicted pick must carry when it leaves your desk?', '["The predicted depth, the relief, the datum, the shift, the displayed depth and the count of wells","The predicted depth, the method, the tolerance, the unit, the operator and the date","The predicted depth or range, the method, the anchor marker, the wells the interval came from, the spread, and an explicit prediction label","The predicted depth, the spread, and the name of the person who produced it"]'::jsonb, 2, 'All six have to be present because a predicted depth loses its qualifiers as it travels. The last distractor is the common short report, and dropping the prediction label is what lets an estimate enter a tops table.'),
  ('wellcorrelation', 'advanced', 'module', 'm05-relief-against-uncertainty', 12, 'Why is 1676.5 m the wrong single value to report for Ekene-4''s TOP_B?', '["It is arithmetically incorrect, because averaging the layer-cake estimate of 1671 m with the from-TOP_SAND estimate of 1682 m gives 1676 m instead of the value quoted","It is the average of the two estimates, so it is a depth neither method produced and it hides the disagreement that was the most informative result","It falls outside the reported prediction range, which runs from the layer-cake estimate of 1671 m up to the from-TOP_SAND estimate of 1682 m, so it cannot stand","It is deeper than the deepest measured TOP_B of 1662 m"]'::jsonb, 1, 'Averaging the two estimates throws away the only evidence you had about how much to trust either. The last distractor is true of both estimates as well, so it cannot be what makes the average wrong.'),
  ('wellcorrelation', 'advanced', 'module', 'm05-relief-against-uncertainty', 13, 'Why is the entry TOP_B 1671 in a tops spreadsheet a bad report even though the number is correct?', '["The value should have been the from-TOP_SAND estimate of 1682 m, which is the preferred one of the two","The unit is missing, and a depth written without a unit cannot be interpreted at all","1671 m sits inside the relief band, which makes it ambiguous","Every qualifier is missing, so the cell looks exactly like the measured picks above it and a reader will treat it as one"]'::jsonb, 3, 'Bad reports are usually short rather than wrong, and this one is bad because nothing in it says the depth was predicted. An unlabelled predicted depth becomes a control point and then a contour.'),
  ('wellcorrelation', 'advanced', 'module', 'm05-relief-against-uncertainty', 14, 'Which of these would turn the Ekene-4 TOP_B range into a pick?', '["Deepening Ekene-4 and logging through TOP_B","A seismic reflector tied to TOP_B in the three carriers and followed to the Ekene-4 location","A nearby well that penetrates TOP_B and adds a fourth carrier to both interval means","A third interval method worked on the same three wells that carry TOP_B"]'::jsonb, 0, 'Only a penetration of the surface in that well produces a pick there. A seismic tie and a nearby well add evidence and change the range, and a third method on the same three wells adds no data at all.'),
  ('wellcorrelation', 'advanced', 'module', 'm05-relief-against-uncertainty', 15, 'A new well close to Ekene-4 penetrates TOP_B. What does that change, and can the spread widen?', '["Only the relief changes, since a new pick extends the range of drilled TOP_B depths","The means are unaffected and the spread narrows toward zero as data are added","Both means become four-well means, so both predictions and the spread move, and the spread can widen, which is a real result rather than a failure","Nothing changes until Ekene-4 itself is deepened"]'::jsonb, 2, 'A fourth carrier changes the divisor and both means, and whether the spread narrows depends on how the new well''s intervals compare with the existing three. A widening spread says the section grows more than three wells could show.'),
  ('wellcorrelation', 'advanced', 'module', 'm06-the-prediction-workflow', 1, 'In the eight-step Expert path, which steps involve arithmetic?', '["Confirming that the gap is a total-depth gap, identifying the wells that carry the target, and choosing the anchor markers to project from","Computing the mean interval for each anchor, projecting each mean from its anchor, and taking the spread","Reading the structural relief, writing the report, and labelling the result as a prediction rather than a pick","Every step, since each one produces a number that ends up being graded"]'::jsonb, 1, 'Only steps four, five and six are arithmetic. The rest of the path is deciding what you are allowed to use and saying what you did, which is where most of the marks are actually lost.'),
  ('wellcorrelation', 'advanced', 'module', 'm06-the-prediction-workflow', 2, 'Which sentence describes the three tiers of this ladder in the right order?', '["The Associate tier picked tops, the Professional tier predicted missing picks, and this tier maps the surfaces","All three tiers predict missing picks, with more wells brought in at each level","The Associate tier flattened, the Professional tier read relief, and this tier averages the two estimates","The Associate tier read the section, the Professional tier flattened it and measured growth, and this tier turned that growth into a prediction with an honest range"]'::jsonb, 3, 'Each tier works the same four wells and the same engine, and what changes is the question. The growth measured at the Professional tier is exactly what makes the prediction here uncertain.'),
  ('wellcorrelation', 'advanced', 'module', 'm06-the-prediction-workflow', 3, 'Ekene-4''s TOP_A pick is revised by 2 m. Which of the six graded numbers move?', '["The layer-cake estimate and the spread, because Ekene-4 contributes no interval to either mean","The mean TOP_A to TOP_B interval and the layer-cake estimate that is projected from it, since Ekene-4 is one of the wells the mean is taken over","Every number except the relief, since all of the other five depend on Ekene-4 in some way","None of the six, because Ekene-4 has no TOP_B pick of its own"]'::jsonb, 0, 'Ekene-4 supplies only anchor depths, so a revised TOP_A moves the projection from TOP_A and the spread that follows. The first distractor is the recurring error of counting Ekene-4 among the wells the mean is taken over.'),
  ('wellcorrelation', 'advanced', 'module', 'm06-the-prediction-workflow', 4, 'A colleague reports a mean TOP_A to TOP_B interval of 105.75 m. What went wrong?', '["The three intervals were entered as depths of 140, 150 and 133 m rather than as intervals measured from the anchor","The mean was taken over the TOP_SAND to TOP_B intervals instead of the TOP_A to TOP_B intervals","The mean was divided by four rather than three, so a well that has no TOP_B was counted in the denominator","The anchor depth of 1530 m was subtracted twice"]'::jsonb, 2, 'The intervals sum to 423 m, and 423 divided by 4 is 105.75 m while the correct three-well mean is 141 m. The divisor is the tell, since Ekene-4 cannot contribute an interval to a surface it does not have.'),
  ('wellcorrelation', 'advanced', 'module', 'm06-the-prediction-workflow', 5, 'Following that 105.75 m mean through, what layer-cake estimate and what spread would be reported?', '["1635.75 m and a spread of 11 m, because the spread is fixed by the method rather than by the mean","1671 m and a spread of 46.25 m, because the prediction stays anchored on the measured TOP_A pick","1659 m and a spread of 12 m, which is what the same divisor error produces","1635.75 m and a spread of 46.25 m"]'::jsonb, 3, 'The error carries through as 1530 plus 105.75, which is 1635.75 m, and then 1682 minus 1635.75, which is 46.25 m. A reported spread larger than the 34 m relief should itself look wrong to you.'),
  ('wellcorrelation', 'advanced', 'module', 'm06-the-prediction-workflow', 6, 'Why must the anchor marker be a pick the target well actually has?', '["Otherwise the mean interval cannot be computed at all from the three wells that carry the target surface, since the anchor sets the top of every interval","Otherwise the anchor depth is itself an estimate, so the result is an estimate projected from an estimate with no way to separate the two errors","Otherwise the tolerance of 0.01 m on the graded prediction cannot be met by hand arithmetic alone, which is what the capstone is designed to expect","Otherwise the structural relief of the anchor surface changes"]'::jsonb, 1, 'Ekene-4 carries TOP_A at 1530 m and TOP_SAND at 1590 m, so both anchors used here are real picks. The check is absolute, since an anchor that had to be estimated first makes the whole prediction undefendable.'),
  ('wellcorrelation', 'advanced', 'module', 'm06-the-prediction-workflow', 7, 'Why is computing only the layer-cake estimate an incomplete result?', '["The layer-cake estimate is always the less defensible of the two, so the other one has to be reported in its place","The capstone grades four fields rather than six when one of the two estimates is missing","A single prediction has no range, and the second estimate is the only source of an uncertainty statement the method can produce","The structural relief cannot be read until both estimates are in hand"]'::jsonb, 2, 'The second estimate is not a cross-check on the first, it is where the range comes from. Stopping at 1671 m is the difference between a result and a number.'),
  ('wellcorrelation', 'advanced', 'module', 'm06-the-prediction-workflow', 8, 'A report gives Ekene-4 TOP_B as 1676 m with an uncertainty of 34 m. Which QC check fails, and what is the 34 m?', '["The check that keeps relief separate from spread, and the 34 m is the structural relief of TOP_B over the three wells that carry it","The check that both of the estimates were computed, and the 34 m is the correct spread to report for a section that grows by as much as this one does","The check that the anchor exists in the target well, and the 34 m is the growth range doubled","No check fails, since 34 m is the more conservative of the two available ranges"]'::jsonb, 0, 'Quoting the relief as the prediction uncertainty is the classic mistake at this tier, and it is roughly three times the measured disagreement of 11 m. The 1676 m is also close to the average of the two estimates, which hides the disagreement.'),
  ('wellcorrelation', 'advanced', 'module', 'm06-the-prediction-workflow', 9, 'What tolerance do the six graded fields of the Expert capstone carry?', '["Four carry 0.01 m and the two counts carry a tolerance of 0, since a count has no margin to be nearly right within","The four depth fields carry 0.01 m while the spread and the relief carry the tighter 0.001 m","The two predictions carry 0.01 m and the two mean intervals have to be exact","All six carry 0.01 m, so this capstone has no exact-match field"]'::jsonb, 3, 'The migration sets a tolerance of 0.01 on every one of the six fields, and all six are quoted in metres. The first distractor imports the count fields from other capstones, and there are no count fields in this one.'),
  ('wellcorrelation', 'advanced', 'module', 'm06-the-prediction-workflow', 10, 'Why does an error in one of the two mean intervals cost three graded fields rather than one?', '["Each prediction is its mean plus a fixed anchor depth, so the error carries into the prediction metre for metre and then into the spread","Because the two mean intervals of 141 m and 92 m are averaged together into a single figure before either of the two predictions is projected","Because the structural relief of TOP_B is computed from the two predictions and therefore inherits any error that manages to reach either of them","Because a tolerance of 0.01 m is too tight to absorb an error of any size"]'::jsonb, 0, 'The mean, its prediction and the spread form a chain, so one divisor slip loses three fields. The second distractor embodies the error of deriving the relief from the predictions, when it is read from three measured picks.'),
  ('wellcorrelation', 'advanced', 'module', 'm06-the-prediction-workflow', 11, 'You have entered 1671 m, 1682 m and a spread of 12 m. What does that tell you?', '["The spread is within tolerance of the correct 11 m, so all three of the fields will pass the grader","One of the three fields was produced separately from the others, since the spread has to be the difference of the two predictions","The two predictions are wrong and the spread of 12 m is the field to keep","The relief should be re-read, since the relief constrains what the spread can be"]'::jsonb, 1, 'Field five is a reconciliation rather than an independent measurement, and 1682 minus 1671 is 11 m. A tolerance of 0.01 m gives no room for 12 m, so the first distractor fails on the arithmetic as well as on the principle.'),
  ('wellcorrelation', 'advanced', 'module', 'm06-the-prediction-workflow', 12, 'Which of the six graded fields is not derived from the predictions at any point?', '["The spread, which is read straight off the panel rather than computed from anything","The mean TOP_SAND to TOP_B interval, which is measured in Ekene-4 itself","The TOP_B structural relief, which comes from three measured picks and would still be 34 m if no prediction had ever been attempted","The layer-cake estimate, which is anchored on a measured pick"]'::jsonb, 2, 'The relief comes from 1640, 1662 and 1628 m and owes nothing to the prediction. Treating the spread as an independent panel reading is the mistake behind the first distractor, since it must reconcile with the two predictions.'),
  ('wellcorrelation', 'advanced', 'module', 'm06-the-prediction-workflow', 13, 'A learner averages the TOP_SAND to TOP_B intervals over four wells. Which fields change, and to what?', '["The mean becomes 69 m, the from-TOP_SAND estimate becomes 1659 m, and the spread becomes 12 m","The mean becomes 69 m, the layer-cake estimate becomes 1659 m, and the structural relief becomes 12 m","All six fields change, because the two mean intervals feed everything else on the sheet","Only the spread changes, since the anchor depth absorbs the error"]'::jsonb, 0, 'The intervals sum to 276 m, so 276 divided by 4 is 69 m, then 1590 plus 69 is 1659 m and 1671 minus 1659 is 12 m. Fields one, three and six are untouched, and the first distractor also derives the relief from a prediction.'),
  ('wellcorrelation', 'advanced', 'module', 'm06-the-prediction-workflow', 14, 'Which of these is outside what a well correlation study can tell you?', '["How much a named surface varies in depth across the wells of the section that actually carry that surface","How thick a named interval is in each individual well, and how much that thickness changes from well to well across the section","Which named surface picked in one well is the same geological surface as the one picked in another well","What the rock does between the wells, since every number in the course is defined at a well location"]'::jsonb, 3, 'The section drawn between two wells is a drawing, and the correlation line joining two picks is a statement of correlation rather than a measurement halfway along. The other three are exactly what correlation is for.'),
  ('wellcorrelation', 'advanced', 'module', 'm06-the-prediction-workflow', 15, 'What do mapping and volumetrics each take from a correlation study?', '["Mapping takes the interval thicknesses and volumetrics takes the structural relief of each named surface with its well count","Mapping takes the picks as control points, and volumetrics takes the surfaces and the intervals between them","Both take the predicted depths rather than the measured ones, which is why a prediction label is not needed above this course","Mapping takes the flattened section and volumetrics takes the datum"]'::jsonb, 1, 'Your correlated tops become somebody''s control points and your intervals become the gross rock volume a resource number rests on. The second distractor is why the labelling discipline matters, since an unlabelled prediction becomes a wrong contour and then a wrong volume.'),
  ('wellcorrelation', 'advanced', 'final', null, 1, 'You intend to treat the TOP_A to TOP_B interval as constant across this section. What makes that a respectable move rather than a forbidden one?', '["Nothing can make it respectable, because the growth range of 14 m rules the assumption out of use entirely.","Stating it openly as an approximation, with the contradicting measurement acknowledged.","The close agreement of the three carrying wells, whose intervals differ by only a metre or two.","The grading tolerance, which allows for the variation."]'::jsonb, 1, 'Made openly, the assumption gives a reader everything needed to judge it and to disagree with it. Declaring it unusable is the opposite error, and the claim that the carriers agree closely is false, since their intervals span 17 m.'),
  ('wellcorrelation', 'advanced', 'final', null, 2, 'Apply the layer-cake method to Ekene-1 using the two other carriers, then compare against its logged TOP_B. What happens?', '["1641.5 m predicted against a logged 1640 m, which is an overshoot of 1.5 m in the one well where the method can be checked.","1641.5 m predicted against 1640 m logged, which validates the method for use at Ekene-4.","1671 m predicted against 1640 m logged.","The test cannot be run at all."]'::jsonb, 0, 'The other two carriers give 150 m and 133 m, a mean of 141.5 m, and 1500 plus 141.5 is 1641.5 m. Reading that small miss as validation is the classic error, because the test rests on two wells and Ekene-1 happens to sit nearest the mean.'),
  ('wellcorrelation', 'advanced', 'final', null, 3, 'How does the layer-cake estimate of 1671 m sit against the three logged TOP_B depths?', '["Shallower than all three, which is what the deepest TOP_A on the section would require.","Between Ekene-3''s 1628 m and Ekene-2''s 1662 m.","Equal to Ekene-2''s 1662 m, the deepest logged value.","Deeper than all three of them."]'::jsonb, 3, 'Ekene-4 carries the deepest TOP_A at 1530 m, so a predicted TOP_B below 1662 m, 1640 m and 1628 m is what a coherent structure produces. The longest option inverts the structural argument, which is the classic error in this check.'),
  ('wellcorrelation', 'advanced', 'final', null, 4, 'Which depth anchors the layer-cake projection into Ekene-4?', '["Ekene-2''s TOP_A at 1512 m, since Ekene-2 carries the thickest interval and is therefore the safest reference.","The datum depth used when the section was flattened at the tier below.","The average TOP_A of the three carrying wells.","Ekene-4''s own measured TOP_A at 1530 m."]'::jsonb, 3, 'The anchor is the one term that belongs to the well being predicted into, which is what ties the result to that hole. Anchoring on another well''s TOP_A is the classic error, and it produces a depth in the wrong wellbore.'),
  ('wellcorrelation', 'advanced', 'final', null, 5, 'Why can Ekene-4 not contribute to the mean TOP_A to TOP_B interval?', '["It can contribute, because its TOP_A at 1530 m is measured and the missing end can be supplied from the mean of the other three.","It has no TOP_B, so that interval cannot be measured in that well at all.","It is excluded because its section is atypically thick.","It was drilled after the other three wells."]'::jsonb, 1, 'The mean is built from wells other than the one being predicted into, which is the structural weakness of the method. Supplying the missing end from the mean and then averaging it back in is the classic circular error.'),
  ('wellcorrelation', 'advanced', 'final', null, 6, 'Why can the prediction not be anchored on TOP_B itself?', '["TOP_B can be used, since its mean depth across the carriers gives a direct estimate for the fourth well.","TOP_B is the surface being predicted, so anchoring on it would assume the answer.","TOP_B lies deeper than total depth in every well on the section.","TOP_B is not a correlatable surface."]'::jsonb, 1, 'An anchor has to be a marker the target well actually carries, and Ekene-4 carries TOP_A, TOP_SAND and BASE_SAND. Anchoring on the missing surface is the classic circular error, and averaging the carriers'' TOP_B depths is the same mistake in another dress.'),
  ('wellcorrelation', 'advanced', 'final', null, 7, 'Reading the TOP_SAND to TOP_B column of 92, 97 and 87 m, which wells set the ends?', '["The column cannot be ordered until Ekene-4''s value has been predicted and added to it.","Ekene-3 is thickest at 97 m and Ekene-1 is thinnest at 87 m.","Ekene-2 is thickest at 97 m, Ekene-3 thinnest at 87 m.","Ekene-1 is thickest at 92 m, Ekene-2 thinnest."]'::jsonb, 2, '1662 minus 1565 is 97 m in Ekene-2 and 1628 minus 1541 is 87 m in Ekene-3. Waiting for the predicted well before ordering the column is the classic error, since a prediction is an output of this table rather than an input to it.'),
  ('wellcorrelation', 'advanced', 'final', null, 8, 'Ekene-2 is the thickest and Ekene-3 the thinnest in both interval columns. What does that consistency support?', '["Mild support for the section varying smoothly, which three wells cannot establish on their own.","Proof that the section varies smoothly, so a mean interval can be transferred with confidence.","Proof that no fault lies between any of the wells.","A reason to drop the thinnest well from the mean."]'::jsonb, 0, 'Consistent ordering is better than its absence and it is not evidence of a trend, because three points give no spatial control. Promoting it to proof is the classic error, and dropping a well on the strength of it is worse.'),
  ('wellcorrelation', 'advanced', 'final', null, 9, 'How is the growth range of the TOP_A to TOP_SAND interval obtained?', '["The mean of the four intervals minus the smallest of them, which is what makes it a growth measure.","The spread of the TOP_A picks across the four wells, which is 35 m.","The maximum minus the minimum, so 60 minus 46, which is 14 m.","It is the same as the spread of the TOP_A to TOP_B values."]'::jsonb, 2, 'Ekene-4 carries the thickest at 60 m and Ekene-3 the thinnest at 46 m, so the range is 14 m. Confusing the range of an interval with the spread of a single surface is the classic error, and the second is a structural relief.'),
  ('wellcorrelation', 'advanced', 'final', null, 10, 'What kind of number is 1671 m?', '["A predicted measured depth in Ekene-4''s own frame.","A displayed depth, because it was produced by adding an interval to a pick after the section had been flattened.","An interval, since a mean interval produced it.","A logged pick carrying a wide tolerance."]'::jsonb, 0, 'It is a depth in the well''s own reference frame, arrived at by inference rather than observation. Calling it a displayed depth is the classic error, since no datum or shift entered the calculation at any point.'),
  ('wellcorrelation', 'advanced', 'final', null, 11, 'What would happen if 1671 m were typed into Ekene-4''s TOP_B slot in the tops table?', '["The well count would stay at 3, because a predicted value is flagged in the table and excluded from statistics automatically.","The count of wells carrying all four tops would rise from 3 to 4, and every TOP_B statistic would silently mix three observations with one inference.","Nothing that matters would change, because the estimate is defensible.","The correlation line would become more honest."]'::jsonb, 1, 'A complete tops table looks healthier than an incomplete one to every automated check anybody runs, which is what makes the corruption silent. Expecting the table to flag the value is the classic error, since a tops table has no column for provenance.'),
  ('wellcorrelation', 'advanced', 'final', null, 12, 'In the projection into Ekene-4, where does the prediction error come from and how does it scale?', '["From both terms, and it is damped, because averaging three wells reduces the error by a factor of three.","From the addition, which cannot be checked.","From the borrowed mean interval, which passes through undamped, giving one metre of prediction error for each metre the true interval differs.","From the grading tolerance."]'::jsonb, 2, 'The anchor is a measurement in the well itself, so the transfer risk lives entirely in the borrowed interval and passes through undamped. Expecting averaging to shrink the error is the classic error, since averaging three wells does not make the fourth well average.'),
  ('wellcorrelation', 'advanced', 'final', null, 13, 'Above TOP_SAND, how does Ekene-4 compare with the thickest of the three contributing wells?', '["It is 7 m thicker, since 60 minus 53 is 7.","It is 14 m thicker, which is the growth range and therefore the difference from the thickest contributor.","It is 7 m thinner, since it carries the smallest interval of the four.","It is the same, since 60 m is the average of the section."]'::jsonb, 0, 'Ekene-4 carries 60 m and the thickest contributor, Ekene-2, carries 53 m. Quoting the growth range of 14 m as the gap to the thickest contributor is the classic error, because that range is measured against the thinnest well rather than against a contributor.'),
  ('wellcorrelation', 'advanced', 'final', null, 14, 'Given that the layer-cake estimate is known to be weak at Ekene-4, what is the right next move?', '["Adjust 1671 m deeper by hand, in proportion to how much thicker Ekene-4''s upper interval is than the average.","Drop the layer-cake estimate and report no depth at all.","Widen the reported tolerance and release the number.","Build a second estimate from a different marker that Ekene-4 does carry, and compare the two constructions."]'::jsonb, 3, 'A second construction turns a described weakness into a measured quantity, which a hand adjustment cannot do. Nudging the number is the classic error, because it replaces a stated assumption with a private one that no reader can check or revise.'),
  ('wellcorrelation', 'advanced', 'final', null, 15, 'Ekene-1 has TOP_SAND at 1548 m and TOP_B at 1640 m, Ekene-2 has 1565 m and 1662 m, and Ekene-3 has 1541 m and 1628 m. What is the mean TOP_SAND to TOP_B interval?', '["49 m, which is the mean TOP_A to TOP_SAND interval across the same wells.","97 m, the largest of the three intervals.","276 m, the total of the three intervals.","92 m."]'::jsonb, 3, 'The intervals are 92, 97 and 87 m, which sum to 276 and divide by 3 to give 92 m. The 49 m option is the carriers'' mean over the stretch above TOP_SAND, which belongs to the identity rather than to the projection.'),
  ('wellcorrelation', 'advanced', 'final', null, 16, 'Which arithmetic produces the from TOP_SAND prediction of Ekene-4''s TOP_B?', '["1510 plus 92, using the displayed TOP_SAND on the 1450 m datum.","1590 plus 92, both measured depths.","1530 plus 92, the mean measured from TOP_SAND.","1590 plus 141."]'::jsonb, 1, 'The anchor is Ekene-4''s measured TOP_SAND and the borrowed interval is the mean measured from TOP_SAND in the carriers. Using the displayed depth is the frame error, and pairing 1530 with 92 mismatches the anchor with an interval measured from a different marker.'),
  ('wellcorrelation', 'advanced', 'final', null, 17, 'Suppose Ekene-4''s TOP_SAND had been picked at 1580 m instead, with every other pick unchanged. Using the identity, what would the spread between the two predictions be?', '["21 m, since the anchor moved 10 m and the spread moves with it.","11 m, unchanged, since the layer-cake estimate does not move.","1 m.","10 m."]'::jsonb, 2, 'The well''s A-to-SAND interval would become 50 m against the carriers'' mean of 49 m, so the identity gives a spread of 1 m. Holding the spread at 11 m ignores that only one of the two predictions is anchored on TOP_SAND.'),
  ('wellcorrelation', 'advanced', 'final', null, 18, 'Suppose Ekene-3''s TOP_B were repicked 3 m deeper at 1631 m. The from TOP_SAND prediction moves from 1682 m to 1683 m. Why does it move less than the repick?', '["The borrowed interval is a mean of three wells, so a change in one is divided by three.","Because the prediction is anchored on a measured pick, and an anchored prediction resists changes in the wells it borrows from.","Because the layer-cake estimate absorbs the rest of the change.","Because a repick of 3 m is within tolerance."]'::jsonb, 0, 'A 3 m change in one of three intervals moves the mean by 1 m, which is the whole of the movement. The damping is real and it cuts both ways, since the mean is also slow to respond to a well that genuinely differs.'),
  ('wellcorrelation', 'advanced', 'final', null, 19, 'The tier below measured an A-to-SAND growth range of 14 m across the four wells. How does that relate to the 11 m spread?', '["The spread and the growth range are the same quantity measured twice.","Growth is why the two methods disagree at all, and the size of the disagreement depends on how far the target well sits from the carriers'' mean thickness.","The growth range sets an upper limit that the spread can never exceed.","The spread is the growth range minus the number of carriers."]'::jsonb, 1, 'Without growth the identity returns zero and the methods agree, so growth is the cause, and the magnitude follows from one well''s departure from the carriers'' mean rather than from the range across all four. Equating 11 m with 14 m collapses two different measurements into one.'),
  ('wellcorrelation', 'advanced', 'final', null, 20, 'The carriers'' mean TOP_A to TOP_SAND interval can be reached two ways. Which pair of routes both give 49 m?', '["Averaging 48, 53, 46 and 60, which brings in Ekene-4, or 141 minus 92.","Averaging the three TOP_SAND to TOP_B intervals, or 1682 minus 141.","Averaging 140, 150 and 133, or 141 minus 60.","Averaging 48, 53 and 46, or 141 minus 92."]'::jsonb, 3, 'The carriers'' A-to-SAND values are 48, 53 and 46, averaging to 49, and the same number falls out of the two graded means as 141 minus 92. Including Ekene-4''s 60 m gives the four well figure and breaks the identity, since the identity subtracts the carriers'' mean from that well''s own value.'),
  ('wellcorrelation', 'advanced', 'final', null, 21, 'Ekene-4''s TOP_A to TOP_SAND interval of 60 m is the thickest in the section, against a 46 to 60 m range across the four wells. Which route is exposed to that, and why?', '["The layer-cake route, because it borrows an average that assumes Ekene-4 is typical over a stretch where it is not.","The from TOP_SAND route, because its anchor lies at the base of the thick stretch, so the extra thickness is carried straight into the borrowed interval.","Both routes equally, since both use the same three carriers.","Neither route, since the thickness is measured rather than assumed."]'::jsonb, 0, 'The layer-cake route projects straight through the thickened stretch on a borrowed average, while the from TOP_SAND route starts below it with that thickness already recorded in the anchor. The exposure belongs to one route, which is why the two answers differ.'),
  ('wellcorrelation', 'advanced', 'final', null, 22, 'What are the spreads of the two sets of borrowed intervals?', '["17 m for TOP_SAND to TOP_B and 10 m for TOP_A to TOP_B, since the longer interval is the more consistent one.","11 m for TOP_SAND to TOP_B and 14 m for TOP_A to TOP_B, the spread and the growth range.","10 m for TOP_SAND to TOP_B and 17 m for TOP_A to TOP_B.","14 m and 17 m."]'::jsonb, 2, 'The SAND-to-B intervals of 87, 92 and 97 spread 10 m and the A-to-B intervals of 133, 140 and 150 spread 17 m. Reversing them inverts the evidence, since the shorter interval is the one the carriers agree about more closely.'),
  ('wellcorrelation', 'advanced', 'final', null, 23, 'A report gives a predicted TOP_B for Ekene-4 of 1682 m, names the two projections and gives the range as about 1671 to 1682 m. Which required element is still missing?', '["A statement that the value is an estimate rather than a pick, so that Ekene-4''s entry in the tops table stays blank and the well count stays at 3.","The number of decimal places carried through the arithmetic, without which the range cannot be reproduced.","The flattening datum used for the section, without which the depths cannot be checked.","The structural position of TOP_B."]'::jsonb, 0, 'Value, method and range are present, and the status of the result is the element that keeps a prediction from being read as a pick. The datum is irrelevant because the prediction is built and reported in measured depth.'),
  ('wellcorrelation', 'advanced', 'final', null, 24, 'What would settle where TOP_B sits in Ekene-4?', '["A seismic horizon tied to TOP_B in the three carriers and carried across Ekene-4, which would remove the need for the range.","A fourth well carrying TOP_B, which would fix the mean interval.","Deepening the well until TOP_B is logged.","Averaging more methods until the estimates converge."]'::jsonb, 2, 'Only a pick in that wellbore turns the estimate into a measurement. A tie or an extra well can narrow the range without closing it, and adding methods produces more estimates rather than an observation.'),
  ('wellcorrelation', 'advanced', 'final', null, 25, 'Beyond destroying the range, what is wrong with the half metre in a reported 1676.5 m?', '["Nothing, since rounding it to 1677 m would fix the problem.","It disagrees with both of the estimates that produced it.","It should have been 1676 m, since depths round down.","It is an artefact of dividing an odd difference by two, and it implies a precision that picks recorded to the metre cannot support."]'::jsonb, 3, 'The decimal appears because 11 is odd and it will be read by somebody as evidence of care in a well where the surface was never reached. Rounding does not help, since the problem is the implied precision rather than the digit.'),
  ('wellcorrelation', 'advanced', 'final', null, 26, 'If 1682 m is reported as the single preferred value, what shape does the range around it have?', '["Symmetric, so it should be written as 1676.5 m plus or minus 5.5 m, which keeps the same two end points.","Asymmetric, since the alternative estimate lies 11 m shallower rather than half that either side.","There is no range once a single value is chosen.","Symmetric, at plus or minus 11 m."]'::jsonb, 1, 'The two estimates are the end points, so a preferred value at the deep end has the whole range below it. Rewriting it as a midpoint with a plus or minus reintroduces the average the module refused, even though the end points look unchanged.'),
  ('wellcorrelation', 'advanced', 'final', null, 27, 'Which finding would most weaken the case for preferring the from TOP_SAND estimate?', '["Evidence that Ekene-4 is the deepest well in the section on every marker it carries, which the section already shows.","Evidence that the layer-cake projection is longer than 141 m.","Evidence that TOP_SAND is poorly picked in the carriers.","Evidence that the two estimates differ by 11 m."]'::jsonb, 2, 'The preference rests on the borrowed interval having clean control, so doubt about the TOP_SAND picks in the carriers attacks it directly. The other findings restate things the section already established and change nothing about the grounds.'),
  ('wellcorrelation', 'advanced', 'final', null, 28, 'In a target well that ran thin over the TOP_A to TOP_SAND stretch, which estimate would land deeper?', '["The layer-cake estimate, because the identity is signed and a thin well sits below the mean.","The from TOP_SAND estimate, because projecting from the deeper anchor always gives the deeper answer.","Neither, since the two estimates would agree exactly in that case.","The from TOP_SAND estimate, by exactly 11 m."]'::jsonb, 0, 'A well thinner than the carriers over the upper stretch makes the identity negative, so the from TOP_SAND result lands shallower and the layer-cake result deeper. The two would agree exactly only if that well sat on the carriers'' mean.'),
  ('wellcorrelation', 'advanced', 'final', null, 29, 'BASE_SAND is picked at 1580, 1601, 1570 and 1615 m. What is its structural relief, and over how many wells?', '["45 m over three wells, since Ekene-4 does not carry a complete column of tops","34 m over four wells, matching the relief already reported for TOP_B","14 m over four wells, which is the growth range of the section","45 m over four wells"]'::jsonb, 3, 'The deepest minus the shallowest is 1615 minus 1570, which is 45 m, and every well carries BASE_SAND so the denominator is four. The three-well denominator belongs to TOP_B alone, and 14 m is a growth range rather than a relief.'),
  ('wellcorrelation', 'advanced', 'final', null, 30, 'Which surface on the Ekene section has the largest structural relief?', '["BASE_SAND, at 45 m, because it is the deepest of the four surfaces that every well carries","TOP_SAND, at 49 m from 1541 m in Ekene-3 to 1590 m in Ekene-4","TOP_B, at 34 m, because it is the surface the whole tier is built around predicting","TOP_A, at 35 m"]'::jsonb, 1, 'The four reliefs are 35 m, 49 m, 45 m and 34 m, so TOP_SAND has the largest. Being the deepest surface does not make a surface the one with the most relief.'),
  ('wellcorrelation', 'advanced', 'final', null, 31, 'Which sentence correctly separates the two quantities?', '["Relief of 34 m is a conservative version of the 11 m spread, so quoting the relief errs on the safe side","The relief is the outer bound and the spread is the inner bound on the same underlying uncertainty","Relief of 34 m is how much TOP_B moves structurally across the section, and the spread of 11 m is how much two methods disagree about one well","They are two readings of the same structural quantity taken at different points in the workflow"]'::jsonb, 2, 'One counts a surface across wells and the other counts methods on a single well. The distractors all treat the relief as a rival estimate of the same thing, which is the classic mistake at this tier.'),
  ('wellcorrelation', 'advanced', 'final', null, 32, 'Relief and spread are different kinds of quantity rather than competing estimates. What is the difference in kind?', '["Relief is a property of drilled geology that exists whether or not anybody predicts anything, and the spread is a property of the estimate that exists only because a prediction was attempted","Relief is measured in metres while the spread is a dimensionless ratio between the two estimates","Relief is a four-well number and the spread is a three-well number","Relief is read after flattening and the spread is read before it"]'::jsonb, 0, 'The 34 m would still be 34 m if Ekene-4 had never been spudded, while the 11 m exists only because two methods were run. Both are in metres, and both here rest on the same three wells.'),
  ('wellcorrelation', 'advanced', 'final', null, 33, 'The three carriers'' A-to-SAND intervals are 48, 53 and 46 m. What is their mean, and what else does that number equal?', '["147 m, which is the sum of the three carriers'' A-to-SAND intervals before the division is carried out","49 m, which is also 141 minus 92, the difference of the two graded mean intervals","60 m, which is Ekene-4''s own A-to-SAND interval and the thickest one anywhere on the section","14 m, the growth range across all four wells of the section"]'::jsonb, 1, 'The three intervals sum to 147 m and 147 divided by 3 is 49 m, which is exactly 141 minus 92. That identity is why Ekene-4''s 60 m minus 49 m gives the 11 m spread exactly rather than approximately.'),
  ('wellcorrelation', 'advanced', 'final', null, 34, 'Which report sentence carries all six required elements of a predicted pick?', '["Ekene-4 TOP_B is estimated at 1682 m from the mean TOP_SAND to TOP_B interval, with a spread of 11 m between the two available methods","Ekene-4 TOP_B predicted between 1671 m and 1682 m, uncertainty 34 m","Ekene-4 TOP_B 1676.5 m","Ekene-4 TOP_B is predicted at 1682 m, projected from that well''s TOP_SAND at 1590 m using the mean TOP_SAND to TOP_B interval of 92 m from the three wells that carry TOP_B, with a layer-cake estimate of 1671 m giving an 11 m spread, so it is a range and not a pick"]'::jsonb, 3, 'The six elements are the depth or range, the method, the anchor marker, the wells, the spread and an explicit prediction label. The second distractor quotes the relief as the uncertainty and the third reports the refused average with no qualifier at all.'),
  ('wellcorrelation', 'advanced', 'final', null, 35, 'A seismic tie is described as evidence rather than a log. Why?', '["The depth it gives carries the uncertainty of the velocity model used to convert time to depth, so it replaces one range with a different range","It cannot be tied to TOP_B in any of the three wells that already carry that surface, so the reflector has nothing at all to calibrate itself against","It measures an interval thickness rather than a depth to the surface itself","It is not independent of the two interval methods already used"]'::jsonb, 0, 'A tie gives a depth at the Ekene-4 location without assuming anything about intervals, which makes it genuinely independent, but the time to depth conversion carries its own error of several metres. Only a penetration of the surface produces a pick.'),
  ('wellcorrelation', 'advanced', 'final', null, 36, 'A seismic tie returns 1690 m for Ekene-4''s TOP_B. What is the honest conclusion?', '["The seismic tie must be wrong, since it falls outside the predicted range that runs from 1671 m up to 1682 m on this section as reported","The reported range should be recentred on 1690 m while keeping the same 11 m spread between the two estimates as before, so nothing else changes","The interval assumption behind both estimates is failing in Ekene-4, so the reported range should be widened rather than defended","The layer-cake estimate of 1671 m should be discarded and the from-TOP_SAND estimate of 1682 m reported on its own as the answer instead"]'::jsonb, 2, 'A result outside the predicted range is information about the method rather than a reason to reject the data. Defending the range against new evidence is how a prediction stops being honest.'),
  ('wellcorrelation', 'advanced', 'final', null, 37, 'A fourth well is drilled that carries TOP_B. Which step of the Expert path must be redone first, and what follows from it?', '["The step that chooses the anchor markers, since the new well may well carry a better marker to project the interval from than either TOP_A or TOP_SAND does","The step that computes the mean interval for each anchor, since both become four-well means and the projections and the spread follow from them","The reporting step, since the only thing that has really changed is the count of the wells carrying the target surface across the section as it is drawn","The step that reads the structural relief, since nothing else on the sheet uses the new well"]'::jsonb, 1, 'A new carrier changes the divisor from three to four, so both means move and everything projected from them moves too. The relief also changes, but it is read separately rather than being the first thing to redo.'),
  ('wellcorrelation', 'advanced', 'final', null, 38, 'After a prediction is produced and reported, what is the state of the tops table and the correlation line?', '["Ekene-4''s TOP_B stays blank, the line still stops after the third well, and the count of wells carrying all four tops stays at 3 of 4","The predicted depth is entered in the tops table in italics as a provisional value, and the count of wells with all four tops rises to 4 of 4","The line is extended across to Ekene-4 while the count stays at 3 of 4","The predicted depth is entered and the count rises to 4 of 4"]'::jsonb, 0, 'A prediction is produced, reported and used, and the blank stays blank. Entering a predicted depth in the tops table is how an estimate becomes a control point and then a contour that nobody can trace back.'),
  ('wellcorrelation', 'advanced', 'final', null, 39, 'Which panel tile do you read the mean TOP_SAND to TOP_B interval from, and what does it show?', '["The prediction from this marker tile, read with the from TOP_SAND marker button active on the panel display","The Ekene-4 TOP_SAND tile, which shows the anchor depth of 1590 m used for the second of the two projections","The spread between them tile, which shows the 11 m gap between the two predicted depths drawn on the chart","The mean TOP_SAND to TOP_B tile, which shows 92 m and is present whichever marker button is selected"]'::jsonb, 3, 'The two mean interval tiles are both always on the panel, so this field does not require switching markers. The prediction from this marker tile shows 1682 m with the from TOP_SAND button active, which is a different graded field.'),
  ('wellcorrelation', 'advanced', 'final', null, 40, 'Which listing gives the six graded capstone fields in the order the assessment defines them?', '["Layer-cake estimate, from TOP_SAND estimate, mean TOP_A to TOP_B, mean TOP_SAND to TOP_B, relief, and then the spread last of all","TOP_B structural relief, the spread between the estimates, then the two predictions, and the two mean intervals last of all","Mean TOP_A to TOP_B, mean TOP_SAND to TOP_B, layer-cake estimate, from TOP_SAND estimate, spread, TOP_B relief","The two predictions, the spread, the relief, and then the two mean intervals"]'::jsonb, 2, 'The two mean intervals come first, then the two predictions built from them, then the spread and the relief. The order follows the dependency, which is also why an error in a mean costs the fields below it.'),
  ('wellcorrelation', 'advanced', 'final', null, 41, 'The Ekene section grows by 14 m across four wells. What can correlation say about the cause of that growth?', '["It measures the thickening and does not identify the mechanism, since growth across a fault is one of several consistent explanations","It identifies a growth fault, because a range of 14 m across four wells is diagnostic of one","It rules faulting out, because the correlation lines run continuously across the section","It identifies compaction, because the deepest well is also the thickest"]'::jsonb, 0, 'Correlation measures thickness change at wells and says nothing about why the accommodation changed. Reading a mechanism straight off a growth range is an interpretation presented as a measurement.'),
  ('wellcorrelation', 'advanced', 'final', null, 42, 'What does the Well Correlation ladder do after the Expert tier?', '["A fourth tier covers seismic-guided correlation across a whole field rather than a single section","Nothing, because there is no tier above it, and the skills feed mapping and volumetrics instead","The Expert tier repeats with more wells added until the prediction spread closes to zero","The ladder continues into Well Data Manager, which sits above this course"]'::jsonb, 1, 'This is the top of the ladder in this app, and the next steps are sideways into mapping and volumetrics. Well Data Manager sits below the ladder, since that is where the wells and the tops table came from.');
